package com.nivor.file;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="document_analyses",indexes=@Index(name="idx_analysis_user_file",columnList="user_id,file_id"))public class DocumentAnalysis extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="file_id",nullable=false)private FileAsset file;@Column(columnDefinition="TEXT")private String summary;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private AnalysisStatus status=AnalysisStatus.PENDING;protected DocumentAnalysis(){}public User getUser(){return user;}public void setUser(User v){user=v;}public FileAsset getFile(){return file;}public void setFile(FileAsset v){file=v;}public String getSummary(){return summary;}public void setSummary(String v){summary=v;}public AnalysisStatus getStatus(){return status;}public void setStatus(AnalysisStatus v){status=v;}}
